CELLS = ['import torch\nimport math\nfrom d2l import torch as d2l\ntorch.manual_seed(0)\nK = 5\n\ndef reward_mean(p):\n    # 选知识点 a 的期望学习收益：答对概率在 0.6 附近时学得最多（太难太易都学得少）\n    return 0.3 * torch.exp(-((p - 0.6) / 0.2) ** 2)\n\ndef sample_states(n):\n    # 每一步的“状态”：模型对 K 个知识点下一题答对概率的预测\n    return torch.rand(n, K) * 0.9 + 0.05\n\ndef mu_policy(p):\n    # 收集日志时用的旧策略 μ：很偏爱容易的知识点（p 越大越常被选），难的很少出\n    return torch.softmax(8 * p, dim=-1)\n\ndef pi_policy(p, T=0.05):\n    # 要评估的新策略 π：论文的规则，偏向答对概率最接近 0.7 的知识点\n    return torch.softmax(-(p - 0.7) ** 2 / T, dim=-1)\n\nx = sample_states(3)\nx.shape, torch.allclose(mu_policy(x).sum(1), torch.ones(3)), pi_policy(x).shape', "def true_value(policy, n=100000):\n    x = sample_states(n)\n    return (policy(x) * reward_mean(x)).sum(1).mean().item()\n\nV_pi, V_mu = true_value(pi_policy), true_value(mu_policy)\nprint(f'新策略 π 的真实价值 {V_pi:.4f}，旧策略 μ 的真实价值 {V_mu:.4f}')\n0.05 < V_mu < V_pi < 0.3", 'def collect_logs(n):\n    x = sample_states(n)\n    a = torch.multinomial(mu_policy(x), 1).squeeze(1)       # 按 μ 抽一个知识点\n    r = reward_mean(x).gather(1, a[:, None]).squeeze(1) + 0.05 * torch.randn(n)   # 观察到的收益（期望值加噪声）\n    return x, a, r\n\nx, a, r = collect_logs(500)\nx.shape, a.shape, a.dtype, r.shape, r.dtype', "print('日志里的平均收益（只能代表 μ）：', round(r.mean().item(), 4), '  真实 V(μ)：', round(V_mu, 4))", "def ope(x, a, r, Q, clip=None, pi=pi_policy):\n    mu_a = mu_policy(x).gather(1, a[:, None]).squeeze(1)      # μ(a | x)\n    pi_all = pi(x)\n    pi_a = pi_all.gather(1, a[:, None]).squeeze(1)            # π(a | x)\n    w = pi_a / mu_a                                           # 重要性权重\n    if clip is not None:\n        w = w.clamp(max=clip)\n    q = Q(x)                                                  # 结果模型：每个动作的预测收益 (n, K)\n    dm = (pi_all * q).sum(1)                                  # 直接法：用模型算 π 的期望收益\n    q_a = q.gather(1, a[:, None]).squeeze(1)\n    return {'IPS': (w * r).mean().item(),\n            'SNIPS': ((w * r).sum() / w.sum()).item(),\n            'DM': dm.mean().item(),\n            'DR': (dm + w * (r - q_a)).mean().item(),\n            'ESS': (w.sum() ** 2 / (w ** 2).sum() / len(w)).item()}\n\nQ_good = lambda x: reward_mean(x)                    # 完全正确的结果模型\nQ_bad = lambda x: 0.6 * reward_mean(x) + 0.05        # 有偏差的结果模型\nest = ope(x, a, r, Q_bad)\nsorted(est.keys()), 0 < est['ESS'] <= 1", "torch.manual_seed(1)\nruns = {k: [] for k in ['IPS', 'SNIPS', 'DM', 'DR']}\nfor rep in range(100):\n    x, a, r = collect_logs(500)\n    e = ope(x, a, r, Q_bad)\n    for k in runs:\n        runs[k].append(e[k])\nfor k, v in runs.items():\n    v = torch.tensor(v)\n    print(f'{k:6s} 平均 {v.mean():.4f}  偏差 {v.mean() - V_pi:+.4f}  标准差 {v.std():.4f}')", "(abs(torch.tensor(runs['DM']).mean().item() - V_pi) > 0.02, abs(torch.tensor(runs['DR']).mean().item() - V_pi) < 0.02, torch.tensor(runs['IPS']).std().item() > torch.tensor(runs['DR']).std().item())", "torch.manual_seed(1)\ndr_good = []\nfor rep in range(100):\n    x, a, r = collect_logs(500)\n    dr_good.append(ope(x, a, r, Q_good)['DR'])\nv = torch.tensor(dr_good)\nprint(f'DR（结果模型正确）平均 {v.mean():.4f}  偏差 {v.mean() - V_pi:+.4f}  标准差 {v.std():.4f}')", "names = ['IPS', 'SNIPS', 'DM', 'DR']\nfor i, k in enumerate(names):\n    d2l.plt.scatter([i + 1 + 0.03 * (j % 9 - 4) for j in range(100)], runs[k], label=k)\nd2l.plt.axhline(y=V_pi, color='k', linestyle='--')\nd2l.plt.xlabel('1 = IPS，2 = SNIPS，3 = DM，4 = DR（每个点是一份日志的估计）')\nd2l.plt.ylabel('估计的 V(π)')\nd2l.plt.legend();", "pi_sharp = lambda p: pi_policy(p, T=0.01)       # 更“尖”的新策略：和 μ 差得更远\nV_sharp = true_value(pi_sharp)\ntorch.manual_seed(2)\nfor clip in [None, 20, 5]:\n    ips, ess = [], []\n    for rep in range(100):\n        x, a, r = collect_logs(500)\n        e = ope(x, a, r, Q_bad, clip=clip, pi=pi_sharp)\n        ips.append(e['IPS']); ess.append(e['ESS'])\n    v = torch.tensor(ips)\n    print(f'截断 {str(clip):4s}：IPS 偏差 {v.mean() - V_sharp:+.4f}  标准差 {v.std():.4f}  平均 ESS {sum(ess) / len(ess):.3f}')"]
